/**
 * User search functionality.
 *
 * @module   mod_casestudy/user
 * @copyright  © Skin Cancer College Australasia
 * @license    Proprietary — Skin Cancer College Australasia, all rights reserved
 */

import UserSearch from 'core_user/comboboxsearch/user';
import * as Repository from 'mod_casestudy/repository';

// Define our standard lookups.
const selectors = {
    component: '.user-search',
    groupid: '[data-region="groupid"]',
    instance: '[data-region="instance"]',
    currentvalue: '[data-region="currentvalue"]',
};
const component = document.querySelector(selectors.component);
const groupID = parseInt(component.querySelector(selectors.groupid).dataset.groupid, 10);
const casestudyID = parseInt(component.querySelector(selectors.instance).dataset.instance, 10);

/**
 * Allow the user to search for users in the action bar.
 *
 * @module    mod_casestudy/user
 * @copyright  © Skin Cancer College Australasia
 * @license    Proprietary — Skin Cancer College Australasia, all rights reserved
 */
export default class User extends UserSearch {

    /**
     * Construct the class.
     *
     * @param {string} baseUrl The base URL for the page.
     */
    constructor(baseUrl) {
        super();
        this.baseUrl = baseUrl;
    }

    /**
     * Allow the class to be invoked via PHP.
     *
     * @param {string} baseUrl The base URL for the page.
     * @returns {User}
     */
    static init(baseUrl) {
        return new User(baseUrl);
    }

    /**
     * Build up the view all link.
     *
     * @returns {string|*}
     */
    selectAllResultsLink() {
        const url = new URL(this.baseUrl);
        url.searchParams.set('search', this.getSearchTerm());

        return url.toString();
    }

    /**
     * Get the data we will be searching against in this component.
     *
     * De-duplicate by user id so a participant never appears more than once in the dropdown.
     *
     * @returns {Promise<*>}
     */
    fetchDataset() {
        return Repository.userFetch(casestudyID, groupID).then((users) => {
            const seen = new Set();
            return users.filter((user) => {
                if (seen.has(user.id)) {
                    return false;
                }
                seen.add(user.id);
                return true;
            });
        });
    }

    /**
     * Handle a selection in the dropdown.
     *
     * The individual matching names are display-only: only the "view all results" entry
     * (value 0) runs the search and filters the submissions list to all matching cases.
     * Selecting a specific name does nothing.
     *
     * @param {Event} e The change event.
     */
    changeHandler(e) {
        if (e.target.value === '0') {
            this.toggleDropdown();
            window.location = this.selectAllResultsLink();
        }
    }

    /**
     * Run the search when the user presses Enter, so typing a name and pressing Enter
     * filters the submissions list without needing to click a dropdown entry.
     *
     * @param {KeyboardEvent} e The keydown event.
     */
    keyHandler(e) {
        if (e.key === 'Enter' && this.getSearchTerm() !== '') {
            e.preventDefault();
            window.location = this.selectAllResultsLink();
            return;
        }
        super.keyHandler(e);
    }

    /**
     * Build up the link that is dedicated to a particular result.
     *
     * Retained for API completeness; the dropdown names are no longer interactive so this
     * is not used by the current flow.
     *
     * @param {Number} userID The ID of the user selected.
     * @returns {string|*}
     */
    selectOneLink(userID) {
        const url = new URL(this.baseUrl);
        url.searchParams.set('search', this.getSearchTerm());
        url.searchParams.set('userid', userID.toString());

        return url.toString();
    }
}
